void ruWear(float w, vec3 p, vec3 n, float rotOn, float charOn, float mossOn, inout vec3 colour, inout float rough, inout float height) {
  if (w <= 0.0) return;
  // the nearness shaken by noise, so each band's edge is ragged and no two breaks wear alike
  vec2 q = p.xz + p.y * 0.37;
  float e = w + (kfbm4(q * 2.3) - 0.5) * 0.45;
  // rain stains: streaks running down the slope, strongest a little off the break where water ran in over the edge
  float streak = kfbm4(vec2(q.x * 9.0, p.y * 1.2));
  float stain = smoothstep(0.05, 0.45, e) * smoothstep(0.4, 0.7, streak);
  colour *= 1.0 - 0.35 * stain;
  // rot: darker, greyer and rougher nearer the break, the grain softened
  float rot = smoothstep(0.25, 0.7, e) * rotOn;
  vec3 grey = vec3(dot(colour, vec3(0.3, 0.5, 0.2)));
  colour = mix(colour, mix(grey, vec3(0.06, 0.05, 0.04), 0.45), rot * 0.85);
  rough = mix(rough, 0.95, rot);
  height *= 1.0 - 0.6 * rot;
  // moss on what faces up, in patches, between the rot and the char
  float up = smoothstep(0.25, 0.75, n.y);
  float moss = up * smoothstep(0.3, 0.55, e) * smoothstep(0.95, 0.75, e) * smoothstep(0.45, 0.65, kfbm(q * 4.1 + 3.3)) * mossOn;
  colour = mix(colour, mix(vec3(0.05, 0.08, 0.02), vec3(0.12, 0.16, 0.04), kn(q * 37.0)), moss);
  height += 0.002 * moss * kn(q * 61.0);
  // the char at the very edge: black, crazed into the squares wood burns into, the cracks deeper
  float burnt = smoothstep(0.72, 0.9, e) * charOn;
  float id, edge;
  kvor(q * 26.0, id, edge);
  float crack = smoothstep(0.08, 0.0, edge) * kfade(0.03);
  colour = mix(colour, vec3(0.025, 0.022, 0.02) * (0.7 + 0.6 * id), burnt);
  rough = mix(rough, 0.9, burnt);
  height = mix(height, 0.0015 * (1.0 - crack) - 0.0015, burnt);
}


vec3 rmRoom(vec3 r, float blur, vec3 sky, vec3 wall, vec3 floorC) {
  float y = clamp(r.y, -1.0, 1.0);
  // floor to wall at the horizon, wall to ceiling above; softer the rougher the face
  float soft = mix(0.015, 0.35, blur);
  vec3 c = mix(floorC, wall, smoothstep(-soft, soft, y));
  c = mix(c, sky, smoothstep(0.45 - soft, 0.45 + soft, y));
  // two tall windows in the walls, a quarter of the way round from each other, from just over the floor to the ceiling
  float az = atan(r.z, r.x);
  float win = 0.0;
  for (int i = 0; i < 2; i++) {
    float centre = float(i) * 1.5707963 + 0.6;
    float d = abs(mod(az - centre + 3.1415926, 6.2831853) - 3.1415926);
    float across = 1.0 - smoothstep(0.22 - soft * 0.5, 0.22 + soft, d);
    float up = smoothstep(0.02 - soft, 0.02 + soft, y) * (1.0 - smoothstep(0.42 - soft, 0.42 + soft, y));
    win = max(win, across * up);
  }
  return mix(c, sky * 2.2, win * (1.0 - 0.45 * blur));
}

















// the cloth's height (0 low to 1 high) and its yarn's lightness (0 to 1) at p, in metres, for the build kind
vec2 upCloth(vec2 p, float kind, float t, float seed) {
  vec2 q = p / t;
  if (kind < 0.5) {
    float warp = sin(q.x * 3.14159), weft = sin(q.y * 3.14159);
    float over = step(0.0, warp * weft);
    float h = mix(abs(weft), abs(warp), over);
    return vec2(0.3 + 0.7 * h, over);
  } else if (kind < 1.5) {
    // twill: floats two over, one under, stepping each row
    float row = floor(q.y);
    float d = fract((q.x + row) / 3.0);
    float over = step(0.34, d);
    float h = abs(sin(fract(q.y) * 3.14159)) * mix(0.6, 1.0, over);
    return vec2(h, over);
  } else if (kind < 2.5) {
    // bouclé: small loops crowded in jittered cells, each a ring of yarn
    float id, e;
    float d = kvor(q, id, e);
    float loopR = 0.32 + 0.1 * fract(id * 13.7);
    float ringH = 1.0 - smoothstep(0.0, 0.16, abs(d - loopR));
    float hump = 1.0 - smoothstep(0.0, 0.62, d);
    return vec2(0.55 * hump + 0.6 * ringH, fract(id * 31.3));
  } else if (kind < 3.5) {
    // mesh: oval holes in offset rows, the knit's bars between them
    vec2 m = vec2(q.x * 0.5, q.y * 0.8);
    m.x += 0.5 * mod(floor(m.y), 2.0);
    vec2 f = fract(m) - 0.5;
    float hole = length(f * vec2(1.0, 1.35));
    return vec2(smoothstep(0.26, 0.4, hole), 1.0 - smoothstep(0.24, 0.3, hole));
  } else if (kind < 4.5) {
    // terry: loops standing up, each a soft tuft in jittered cells, the ground weave between them
    float id, e;
    float d = kvor(q, id, e);
    float tuft = 1.0 - smoothstep(0.1, 0.55, d);
    return vec2(0.25 + 0.75 * tuft, 0.6 + 0.4 * fract(id * 17.1));
  }
  // braid: plaited yarns, a herringbone along u
  float side = sign(fract(q.y * 0.5) - 0.5);
  float s = fract(q.x * 0.7 + side * q.y * 0.7);
  float h = abs(sin(s * 3.14159));
  return vec2(h, step(0.0, side));
}
// a small leaf printed on cotton, repeated rep metres apart, each turned its own way: 1 on the leaf
float upLeaf(vec2 p, float rep, float seed) {
  vec2 cell = floor(p / rep);
  vec2 f = fract(p / rep) - 0.5;
  float a = kh(cell + seed) * 6.2831853;
  vec2 r = vec2(cos(a) * f.x + sin(a) * f.y, -sin(a) * f.x + cos(a) * f.y);
  r += (vec2(kh(cell + 3.1), kh(cell + 5.7)) - 0.5) * 0.15;
  float blade = length(vec2(r.x * 2.6, r.y * 1.0 + 0.4 * r.x * r.x * 8.0));
  float leafM = 1.0 - smoothstep(0.26, 0.29, blade);
  float rib = 1.0 - smoothstep(0.0, 0.02, abs(r.x));
  return leafM * (1.0 - 0.6 * rib * step(abs(r.y), 0.25));
}


// 1 on a tick ring: a the angle from the sweep's start in degrees, step the degrees between marks, r the point's radius
// in the dial's radii from r0 to r1, e the pixel's width in radii
float gfRing(float a, float stepDeg, float r, float r0, float r1, float half_, float e) {
  float k = a / stepDeg;
  float d = abs(fract(k + 0.5) - 0.5) * stepDeg * 0.0174533 * r;
  return (1.0 - smoothstep(half_, half_ + e, d)) * smoothstep(r0 - e, r0, r) * (1.0 - smoothstep(r1, r1 + e, r));
}
// the distance from p to the stroke a to b
float gfStroke(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}
// the distance from p to the digit d drawn in seven strokes, in a cell 0.8 wide and 1.6 high about its middle
float gfDigit(vec2 p, int d) {
  int m = d == 0 ? 63 : d == 1 ? 6 : d == 2 ? 91 : d == 3 ? 79 : d == 4 ? 102 : d == 5 ? 109 : d == 6 ? 125 :
          d == 7 ? 7 : d == 8 ? 127 : 111;
  float r = 1e3;
  if ((m & 1) != 0) r = min(r, gfStroke(p, vec2(-0.4, 0.8), vec2(0.4, 0.8)));
  if ((m & 2) != 0) r = min(r, gfStroke(p, vec2(0.4, 0.8), vec2(0.4, 0.0)));
  if ((m & 4) != 0) r = min(r, gfStroke(p, vec2(0.4, 0.0), vec2(0.4, -0.8)));
  if ((m & 8) != 0) r = min(r, gfStroke(p, vec2(-0.4, -0.8), vec2(0.4, -0.8)));
  if ((m & 16) != 0) r = min(r, gfStroke(p, vec2(-0.4, 0.0), vec2(-0.4, -0.8)));
  if ((m & 32) != 0) r = min(r, gfStroke(p, vec2(-0.4, 0.8), vec2(-0.4, 0.0)));
  if ((m & 64) != 0) r = min(r, gfStroke(p, vec2(-0.4, 0.0), vec2(0.4, 0.0)));
  return r;
}
// 1 on the whole number n written upright about c, its digits size half high, e the pixel's width (in the same units)
float gfNumber(vec2 p, vec2 c, float n, float size, float e) {
  float v = floor(n + 0.5);
  int count = v < 9.5 ? 1 : v < 99.5 ? 2 : 3;
  vec2 q = (p - c) / (size * 0.5);
  float x0 = -float(count - 1) * 0.6;
  if (abs(q.x) > float(count) * 0.6 + 0.4 || abs(q.y) > 1.2) return 0.0;
  float best = 1e3;
  for (int k = 0; k < 3; k++) {
    if (k >= count) break;
    float place = pow(10.0, float(count - 1 - k));
    int d = int(mod(floor((v + 0.5) / place), 10.0));
    best = min(best, gfDigit(q - vec2(x0 + 1.2 * float(k), 0.0), d));
  }
  float w = 0.13;
  float ew = e / (size * 0.5);
  return 1.0 - smoothstep(w, w + ew, best);
}
// where a numeral stands: from degrees along a sweep of sw centred on straight up, at radius r, about pivot
vec2 gfAt(float from, float sw, float r, vec2 pivot) {
  float a = radians(-sw * 0.5 + from);
  return pivot + vec2(sin(a), cos(a)) * r;
}










// the yarn of a tow: 0 carbon, 1 aramid; dirV 1 for a tow running along v (a warp), 0 along u (a weft), n its number
float ckYarn(float n, float dirV, float mixKind) {
  if (mixKind < 0.5) return 0.0;
  if (mixKind < 1.5) return mod(n, 2.0);
  return dirV > 0.5 ? 0.0 : 1.0;
}











// how much of a band w wide, rep apart, is at t: 1 inside one, 0 between, its edges softened by the pixel's size
float wcBand(float t, float rep, float w) {
  float d = abs(fract(t / rep) - 0.5) * rep;
  float edge = max(fwidth(t), 1e-6);
  return 1.0 - smoothstep(w * 0.5 - edge, w * 0.5 + edge, d);
}


float cmLine(float d, float w, float e) { return 1.0 - smoothstep(w, w + e, abs(d)); }
float cmBox(vec2 p, vec2 lo, vec2 hi, float e) {
  return smoothstep(lo.x - e, lo.x, p.x) * (1.0 - smoothstep(hi.x, hi.x + e, p.x)) * smoothstep(lo.y - e, lo.y, p.y) * (1.0 - smoothstep(hi.y, hi.y + e, p.y));
}
// one seven segment digit d in a cell 0.8 wide and 1.6 high about its middle: 1 on a lit segment
float cmDigit(vec2 p, int d, float w, float e) {
  int m = d == 0 ? 63 : d == 1 ? 6 : d == 2 ? 91 : d == 3 ? 79 : d == 4 ? 102 : d == 5 ? 109 : d == 6 ? 125 :
          d == 7 ? 7 : d == 8 ? 127 : 111;
  float r = 0.0;
  // each segment a bar: (its middle, its half size)
  if ((m & 1) != 0) r = max(r, cmBox(p, vec2(-0.32, 0.8 - w), vec2(0.32, 0.8 + w), e));
  if ((m & 2) != 0) r = max(r, cmBox(p, vec2(0.4 - w, 0.06), vec2(0.4 + w, 0.74), e));
  if ((m & 4) != 0) r = max(r, cmBox(p, vec2(0.4 - w, -0.74), vec2(0.4 + w, -0.06), e));
  if ((m & 8) != 0) r = max(r, cmBox(p, vec2(-0.32, -0.8 - w), vec2(0.32, -0.8 + w), e));
  if ((m & 16) != 0) r = max(r, cmBox(p, vec2(-0.4 - w, -0.74), vec2(-0.4 + w, -0.06), e));
  if ((m & 32) != 0) r = max(r, cmBox(p, vec2(-0.4 - w, 0.06), vec2(-0.4 + w, 0.74), e));
  if ((m & 64) != 0) r = max(r, cmBox(p, vec2(-0.32, -w), vec2(0.32, w), e));
  return r;
}
// the number v written with places digits right-aligned about c, dec of them after a point, its digits size high;
// e the pixel's width in the same units
float cmNumber(vec2 p, vec2 c, float v, int places, int dec, float size, float e) {
  vec2 q = (p - c) / (size * 0.5);
  float half_ = float(places) * 0.6 + 0.4;
  if (abs(q.x) > half_ + 0.3 || abs(q.y) > 1.1) return 0.0;
  float ee = e / (size * 0.5);
  float n = floor(v * pow(10.0, float(dec)) + 0.5);
  float ink = 0.0;
  for (int k = 0; k < 5; k++) {
    if (k >= places) break;
    float place = pow(10.0, float(places - 1 - k));
    int d = int(mod(floor(n / place), 10.0));
    // leading zeros left dark, but never the digit before the point
    bool lead = n < place && k < places - 1 - dec;
    float x = -float(places - 1) * 0.6 + 1.2 * float(k);
    // the readouts' big figures in bold segments, as a segment LCD's are; the meters' small ones finer
    if (!lead) ink = max(ink, cmDigit(q - vec2(x, 0.0), d, size > 0.3 ? 0.135 : 0.11, ee));
  }
  if (dec > 0) {
    float xp = -float(places - 1) * 0.6 + 1.2 * float(places - dec) - 0.6;
    ink = max(ink, 1.0 - smoothstep(0.13, 0.13 + ee, length(q - vec2(xp, -0.8))));
  }
  return ink;
}
// a row of short label bars standing for a word: n bars across from x0, their heights alike, about y
float cmWord(vec2 p, float x0, float y, float n, float h, float e) {
  float ink = 0.0;
  for (int i = 0; i < 6; i++) {
    if (float(i) >= n) break;
    float x = x0 + float(i) * h * 0.9;
    ink = max(ink, cmBox(p, vec2(x, y - h * 0.5), vec2(x + h * 0.6, y + h * 0.5), e));
  }
  return ink;
}


void look_0(inout Look k, int lookRow) {
  p_stColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_stMetal = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_stRough = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_stOil = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_stOilColour = texelFetch(lookSettings, ivec2(4, lookRow), 0).rgb;
  p_stOilBrown = texelFetch(lookSettings, ivec2(5, lookRow), 0).rgb;
  p_stOilSize = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_stOilRough = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_stFinPitch = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_stFinShare = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_stFinDepth = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float brush = kn(vec2(uv.x * 4.0, uv.y * 900.0) + seed) * kfade(0.002);
    float wear = kfbm(uv * 3.0 + seed);
    vec3 stC = p_stColour * (0.9 + 0.12 * brush) * (0.9 + 0.15 * wear);
    float stM = p_stMetal;
    float stR = p_stRough + 0.15 * brush + 0.1 * wear;
    float stH = 0.00005 * brush;
    // fins: a rounded ridge of share stFinShare in each pitch along s3.x, the groove between them the depth down and
    // dark (the normal they bend is worked out below); fading to the fins' mean where a pitch is under a few pixels
    float stOn = step(0.5, s3.y);
    float stFade = kfade(p_stFinPitch * 4.0);
    float stF = fract(s3.x / p_stFinPitch);
    float stRidge = smoothstep(1.0 - 2.0 * p_stFinShare, 1.0, 0.5 + 0.5 * cos(6.28318 * stF));
    // far off, the fins' mean: the ridges' share lit, the rest groove
    float stShade = mix(p_stFinShare, stRidge, stFade);
    stC *= mix(1.0, 0.55 + 0.45 * stShade, stOn);
    // burnt castor oil: blotches and runs of a brown-black varnish; thick (glossy, brown in its highlight) or thin
    float stBlot = kfbm(uv * p_stOilSize + seed * 1.7);
    float stRun = kn(vec2(uv.x * p_stOilSize * 0.6, uv.y * p_stOilSize * 9.0) + seed + 11.0);
    float stThick = smoothstep(0.35, 0.75, 0.65 * stBlot + 0.35 * stRun);
    float stO = clamp(p_stOil * (0.75 + 0.35 * stThick), 0.0, 1.0);
    vec3 stOilC = mix(p_stOilColour, p_stOilBrown, stThick * (0.5 + 0.5 * kn(uv * 60.0 + seed)));
    stC = mix(stC, stOilC * mix(1.0, 0.6 + 0.4 * stShade, stOn), stO);
    stM = mix(stM, 0.12, stO);
    stR = mix(stR, mix(0.75, p_stOilRough, stThick), stO);
    stH += p_stOil * 0.00004 * stThick;
    k.colour = stC;
    k.metal = stM;
    k.rough = stR;
    k.height = stH;
    if (stOn > 0.5) {
      // the fins bend the normal from their profile's slope worked out exactly, not from the pixels' neighbours (whose
      // steps break thin rings into dots): the way s3.x grows across the surface, in the view's ways, from its change
      // between pixels (it is even across a face, so this is clean), times the profile's slope along it
      vec3 stN = normalize(vNormal);
      vec3 stPx = dFdx(-vViewPosition), stPy = dFdy(-vViewPosition);
      vec3 stR1 = cross(stPy, stN), stR2 = cross(stN, stPx);
      float stDet = dot(stPx, stR1);
      vec3 stG = (dFdx(s3.x) * stR1 + dFdy(s3.x) * stR2) / (abs(stDet) > 1e-14 ? stDet : 1e-14);
      float stPhi = 6.28318 * stF;
      float stA = 1.0 - 2.0 * p_stFinShare;
      float stT = clamp((0.5 + 0.5 * cos(stPhi) - stA) / (1.0 - stA), 0.0, 1.0);
      float stSlope = p_stFinDepth * 6.0 * stT * (1.0 - stT) / (1.0 - stA) * (-0.5 * sin(stPhi) * 6.28318 / p_stFinPitch);
      k.normal = normalize(stN - stFade * stSlope * stG);
      k.ownNormal = true;
    }

}

void look_1(inout Look k, int lookRow) {
  p_ldRot = texelFetch(lookSettings, ivec2(0, lookRow), 0).r;
  p_ldChar = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_ldMoss = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float oxide = smoothstep(0.55, 0.8, kfbm(uv * 2.0 + seed));
    k.colour = mix(vec3(0.3, 0.31, 0.34), vec3(0.62, 0.63, 0.64), oxide);
    k.metal = mix(0.6, 0.0, oxide);
    k.rough = mix(0.55, 0.9, oxide);
    k.height = 0.0006 * (kfbm(uv * 12.0 + seed) - 0.5);
    float ldWorn = s2.w;
    ruWear(ldWorn, wp, wn, p_ldRot, p_ldChar, p_ldMoss, k.colour, k.rough, k.height);
    // soot and moss take the metal's shine off
    k.metal *= 1.0 - smoothstep(0.2, 0.6, ldWorn);

}

void look_2(inout Look k, int lookRow) {
  p_plColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_plStipple = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_plRelief = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_plRough = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_plRoughVar = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_plTone = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_plThrough = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float plS = kn(uv * p_plStipple + seed) * kfade(2.0 / p_plStipple);
    float plS2 = kn(uv * p_plStipple * 0.37 + seed + 9.0) * kfade(5.0 / p_plStipple);
    float plW = kfbm4(uv * 3.0 + seed);
    k.colour = p_plColour * (1.0 + p_plTone * (plW - 0.5) * 2.0);
    k.rough = clamp(p_plRough + p_plRoughVar * (plW - 0.5) * 2.0 + 0.05 * plS, 0.0, 1.0);
    k.height = p_plRelief * (0.6 * plS + 0.4 * plS2);
    if (p_plThrough > 0.0) {
      float plFace = clamp(abs(dot(normalize(cameraPosition - wp), normalize(wn))), 0.0, 1.0);
      k.glow = p_plThrough * k.colour * (0.45 + 0.55 * plFace) * (0.9 + 0.2 * plW);
    }

}

void look_3(inout Look k, int lookRow) {
  p_rbColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_rbBloom = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_rbBloomAmount = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_rbGrit = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_rbRelief = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_rbRough = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_rbSheen = texelFetch(lookSettings, ivec2(6, lookRow), 0).rgb;
  p_rbSheenRough = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float rbG = kn(uv * p_rbGrit + seed) * kfade(2.0 / p_rbGrit);
    float rbP = 1.0 - smoothstep(0.0, 0.25, kcell(uv * p_rbGrit * 0.25 + seed)) ;
    rbP *= kfade(6.0 / p_rbGrit);
    float rbB = smoothstep(0.35, 0.8, kfbm4(uv * 4.0 + seed)) * p_rbBloomAmount;
    k.colour = mix(p_rbColour, p_rbBloom, rbB) * (0.95 + 0.1 * rbG) * (1.0 - 0.3 * rbP);
    k.rough = clamp(p_rbRough + 0.08 * rbB + 0.05 * rbG, 0.0, 1.0);
    k.height = p_rbRelief * (rbG - 0.6 * rbP);
    k.sheen = p_rbSheen;
    k.sheenRough = p_rbSheenRough;

}

void look_4(inout Look k, int lookRow) {
  p_chColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_chRough = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
