}


void look_6(inout Look k, int lookRow) {
  p_cmColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_cmSand = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_cmRelief = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_cmPits = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_cmRough = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_cmMetal = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_cmBloom = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_cmBloomColour = texelFetch(lookSettings, ivec2(7, lookRow), 0).rgb;
  p_cmHeat = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_cmHeatColour = texelFetch(lookSettings, ivec2(9, lookRow), 0).rgb;
  p_cmGrime = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_cmGrimeColour = texelFetch(lookSettings, ivec2(11, lookRow), 0).rgb;
  p_cmMirror = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  p_cmSky = texelFetch(lookSettings, ivec2(13, lookRow), 0).rgb;
  p_cmWall = texelFetch(lookSettings, ivec2(14, lookRow), 0).rgb;
  p_cmFloor = texelFetch(lookSettings, ivec2(15, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the sand's grain: fine bumps, and here and there a pit, each fading to its mean where finer than a pixel
    float cmF = kfade(2.0 / p_cmSand);
    float cmG = mix(0.5, kn(uv * p_cmSand + seed), cmF);
    float cmG2 = mix(0.5, kn(uv * p_cmSand * 0.43 + seed + 5.0), kfade(4.0 / p_cmSand));
    float cmP = p_cmPits * (1.0 - smoothstep(0.0, 0.22, kcell(uv * p_cmSand * 0.3 + seed + 3.0))) * kfade(8.0 / p_cmSand);
    // the faces that look down (wn.y below 0) carry the oil and road grime, the rest a little of it in patches
    float cmDown = smoothstep(0.15, -0.85, wn.y);
    float cmGr = clamp(p_cmGrime * (0.2 + 0.9 * cmDown) * smoothstep(0.3, 0.75, kfbm(uv * 4.5 + seed + 7.0) + 0.3 * cmDown), 0.0, 1.0);
    float cmB = p_cmBloom * smoothstep(0.45, 0.85, kfbm4(uv * 3.0 + seed + 1.0));
    float cmH = p_cmHeat * smoothstep(0.25, 0.75, kfbm4(uv * 2.2 + seed + 13.0));
    float cmS = 0.6 * cmG + 0.4 * cmG2;
    vec3 cmC = p_cmColour * (0.9 + 0.2 * cmS) * (1.0 - 0.45 * cmP);
    cmC = mix(cmC, p_cmBloomColour, cmB);
    cmC = mix(cmC, p_cmHeatColour * (0.85 + 0.3 * cmS), cmH);
    cmC = mix(cmC, p_cmGrimeColour, clamp(cmGr + 0.6 * cmP * p_cmGrime, 0.0, 1.0));
    k.colour = cmC;
    k.metal = p_cmMetal * (1.0 - 0.5 * cmB) * (1.0 - 0.8 * cmGr);
    k.rough = clamp(p_cmRough + 0.12 * (cmS - 0.5) + 0.2 * cmB + 0.25 * cmGr + 0.2 * cmP, 0.05, 1.0);
    k.height = p_cmRelief * (cmS - 0.5 - 0.9 * cmP) + 0.00003 * cmGr;
    k.ao = 1.0 - 0.35 * cmP;
    // the room mirrored softly, as a satin casting shows it, less where it is bloomed or grimed
    vec3 cmV = normalize(wp - cameraPosition);
    vec3 cmN = normalize(wn);
    float cmCos = clamp(dot(-cmV, cmN), 0.0, 1.0);
    vec3 cmRoom = rmRoom(reflect(cmV, cmN), clamp(p_cmRough * 1.8, 0.0, 1.0), p_cmSky, p_cmWall, p_cmFloor);
    k.glow = p_cmMirror * cmRoom * cmC * (0.7 + 0.3 * pow(1.0 - cmCos, 3.0)) * (1.0 - cmGr) * (1.0 - 0.5 * cmB);

}


void look_8(inout Look k, int lookRow) {
  p_cpColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_cpCrown = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_cpWrinkles = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_cpWander = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_cpRelief = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_cpRough = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_cpCrownRough = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_cpDust = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_cpDustColour = texelFetch(lookSettings, ivec2(8, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the net: the edges of cells in a field warped by noise, so the ridges wander and branch as a wrinkle coat's do;
    // a second, finer net at a slant over it for the small wrinkles between the big ones
    vec2 cpP = uv * p_cpWrinkles + seed * 13.0;
    cpP += p_cpWander * vec2(kn(cpP * 0.35 + 2.0), kn(cpP * 0.35 + 9.0)) * 2.0;
    float cpId, cpE;
    kvor(cpP, cpId, cpE);
    float cpId2, cpE2;
    vec2 cpQ = mat2(0.8, -0.6, 0.6, 0.8) * cpP * 1.9 + 4.0;
    kvor(cpQ, cpId2, cpE2);
    // each net fades to its own mean where its wrinkles are finer than a pixel (the share of the face a ridge covers, as
    // the cells' edges fall), so a face seen from afar is the even satin it looks, with no seam where the fade changes
    float cpF = kfade(1.5 / p_cpWrinkles);
    float cpF2 = kfade(0.8 / p_cpWrinkles);
    float cpRidge = mix(0.3, 1.0 - smoothstep(0.0, 0.32, cpE), cpF);
    float cpRidge2 = mix(0.25, 1.0 - smoothstep(0.0, 0.25, cpE2), cpF2);
    float cpR = max(cpRidge, 0.55 * cpRidge2);
    float cpCr = cpR;
    float cpUp = smoothstep(0.3, 0.9, wn.y);
    float cpD = p_cpDust * cpUp * (1.0 - cpR) * smoothstep(0.35, 0.8, kfbm4(uv * 6.0 + seed + 3.0));
    vec3 cpC = mix(p_cpColour, p_cpCrown, cpCr * (0.7 + 0.6 * cpId));
    cpC = mix(cpC, p_cpDustColour, cpD);
    k.colour = cpC;
    k.metal = 0.0;
    k.rough = clamp(mix(p_cpRough, p_cpCrownRough, cpCr) + 0.3 * cpD, 0.05, 1.0);
    k.height = p_cpRelief * (cpRidge + 0.5 * cpRidge2);
    k.clearcoat = 0.25 * cpCr;
    k.clearcoatRough = 0.35;
    k.ao = 1.0 - 0.25 * (1.0 - cpR) * cpF;

}

void look_9(inout Look k, int lookRow) {
  p_pcTint = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_pcSky = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_pcHorizon = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_pcFloor = texelFetch(lookSettings, ivec2(3, lookRow), 0).rgb;
  p_pcBlur = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_pcWindow = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_pcRough = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 pcN = normalize(wn);
    vec3 pcI = normalize(wp - cameraPosition);
    vec3 pcR = reflect(pcI, pcN);
    // how far up the reflected line points: -1 straight down, 1 straight up
    float pcUp = pcR.y;
    float pcB = p_pcBlur;
    // the floor below, the sky above, a bright band at the horizon between them
    vec3 pcEnv = mix(p_pcFloor, p_pcSky, smoothstep(-pcB, pcB, pcUp));
    pcEnv = mix(pcEnv, p_pcHorizon, exp(-pcUp * pcUp / max(0.002, pcB * pcB * 0.25)) * 0.55);
    // a soft window of light high up and toward one side, so a round part has its one bright spot
    float pcW = smoothstep(0.82, 0.97, dot(pcR, normalize(vec3(0.35, 0.85, 0.4))));
    pcEnv += vec3(p_pcWindow) * pcW;
    // the faint swirls of polishing, gone to their mean where a pixel is as wide
    float pcSw = mix(0.5, kn(uv * 900.0 + seed), kfade(0.002));
    k.colour = clamp(pcEnv * p_pcTint * (0.98 + 0.04 * pcSw), 0.0, 1.0);
    k.metal = 0.0;
    k.rough = p_pcRough;

}

void look_10(inout Look k, int lookRow) {
  p_htBase = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_htStraw = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_htBronze = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_htPurple = texelFetch(lookSettings, ivec2(3, lookRow), 0).rgb;
  p_htBlue = texelFetch(lookSettings, ivec2(4, lookRow), 0).rgb;
  p_htGrey = texelFetch(lookSettings, ivec2(5, lookRow), 0).rgb;
  p_htTint = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_htHeat = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_htPatch = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_htPatchSize = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_htSoot = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_htSootColour = texelFetch(lookSettings, ivec2(11, lookRow), 0).rgb;
  p_htLines = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  p_htStreak = texelFetch(lookSettings, ivec2(13, lookRow), 0).r;
  p_htRough = texelFetch(lookSettings, ivec2(14, lookRow), 0).r;
  p_htMetal = texelFetch(lookSettings, ivec2(15, lookRow), 0).r;
  p_htMirror = texelFetch(lookSettings, ivec2(16, lookRow), 0).r;
  p_htSky = texelFetch(lookSettings, ivec2(17, lookRow), 0).rgb;
  p_htWall = texelFetch(lookSettings, ivec2(18, lookRow), 0).rgb;
  p_htFloor = texelFetch(lookSettings, ivec2(19, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float htH = s3.y > 0.5 ? s3.x : p_htHeat;
    float htN = kfbm4(uv * p_htPatchSize + seed * 1.7);
    float htBand = kfbm4(vec2(uv.x * p_htPatchSize * 0.4, uv.y * p_htPatchSize * 2.5) + seed + 11.0);
    htH = clamp(htH + p_htPatch * (0.65 * htN + 0.35 * htBand - 0.5) * 1.4, 0.0, 1.0);
    float htFine = mix(0.5, kn(vec2(uv.x * 7.0, uv.y * p_htLines) + seed), kfade(2.0 / p_htLines));
    // the temper chart, a colour every fifth of the way
    vec3 htC = p_htBase;
    htC = mix(htC, p_htStraw, smoothstep(0.04, 0.2, htH));
    htC = mix(htC, p_htBronze, smoothstep(0.2, 0.4, htH));
    htC = mix(htC, p_htPurple, smoothstep(0.4, 0.58, htH));
    htC = mix(htC, p_htBlue, smoothstep(0.58, 0.76, htH));
    htC = mix(htC, p_htGrey, smoothstep(0.8, 1.0, htH));
    // the film is thin: the metal's own grey shows through it
    htC = mix(p_htBase, htC, p_htTint);
    htC *= 1.0 + p_htStreak * (htFine - 0.5);
    // soot: matte black drifts, thicker where it was hotter
    float htS = p_htSoot * smoothstep(0.75 - 0.5 * p_htSoot - 0.25 * htH, 0.95 - 0.3 * p_htSoot, kfbm(uv * 3.5 + seed * 0.7) + 0.15 * kn(uv * 60.0 + seed));
    htC = mix(htC, p_htSootColour, htS);
    k.colour = htC;
    k.metal = p_htMetal * (1.0 - 0.9 * htS);
    k.rough = clamp(p_htRough + 0.1 * (htFine - 0.5) + 0.12 * smoothstep(0.8, 1.0, htH) + 0.5 * htS, 0.03, 1.0);
    k.height = 0.000012 * (htFine - 0.5) + 0.00008 * htS * kn(uv * 300.0 + seed);
    vec3 htV = normalize(wp - cameraPosition);
    vec3 htNn = normalize(wn);
    vec3 htR = reflect(htV, htNn) + 0.06 * (htFine - 0.5) * vec3(1.0, 0.0, 1.0);
    float htCos = clamp(dot(-htV, htNn), 0.0, 1.0);
    vec3 htRoom = rmRoom(normalize(htR), clamp(p_htRough * 2.0, 0.0, 1.0), p_htSky, p_htWall, p_htFloor);
    k.glow = p_htMirror * htRoom * htC * (0.7 + 0.3 * pow(1.0 - htCos, 3.0)) * (1.0 - htS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(htH, 0.2, 1.0 - htH);

}



void look_13(inout Look k, int lookRow) {

  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // a velvety near-black crust, browner where tar has run and glazed, flaking in places to a lighter grey ash
    float crust = kfbm(uv * 9.0 + seed);
    float tar = smoothstep(0.55, 0.8, kfbm(vec2(uv.x * 3.0, uv.y * 0.8) + seed + 3.0));
    float flake = smoothstep(0.72, 0.78, kfbm(uv * 14.0 + seed + 9.0));
    vec3 c = mix(vec3(0.016, 0.015, 0.015), vec3(0.04, 0.038, 0.036), crust);
    c = mix(c, vec3(0.05, 0.035, 0.022), tar * 0.5);
    c = mix(c, vec3(0.1, 0.098, 0.095), flake * 0.5);
    k.colour = c * (0.8 + 0.4 * kn(uv * 220.0 + seed) * kfade(0.003));
    k.rough = mix(1.0, 0.7, tar);
    k.height = 0.0012 * crust - 0.0006 * flake;

}

void look_14(inout Look k, int lookRow) {
  p_rdColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_rdTubeColour = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_rdGap = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_rdEdge = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_rdPitch = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_rdTube = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_rdFins = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_rdDepth = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_rdRough = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_rdMetal = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_rdDust = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_rdDustColour = texelFetch(lookSettings, ivec2(11, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 rdW = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the tubes, across them
    vec2 rdQ = vec2(dot(uv, rdW), dot(uv, vec2(-rdW.y, rdW.x)));
    // the rows: a tube's flat face, then the fin's band, a row every pitch across the tubes
    float rdRow = fract(rdQ.y / p_rdPitch);
    float rdT = smoothstep(0.0, 0.04, rdRow) * (1.0 - smoothstep(p_rdTube, p_rdTube + 0.04, rdRow));
    float rdRowsSeen = kfade(p_rdPitch * 1.5);
    rdT = mix(p_rdTube, rdT, rdRowsSeen);
    // the fin's folds along the tubes: each fold's edge a bright thin line, the gap between two folds dark and deep
    float rdFold = fract(rdQ.x * p_rdFins);
    float rdEdge = 1.0 - smoothstep(0.0, 0.22, abs(rdFold - 0.5) * 2.0 - 0.55);
    float rdFoldsSeen = kfade(2.0 / p_rdFins);
    rdEdge = mix(0.4, rdEdge, rdFoldsSeen);
    float rdFin = 1.0 - rdT;
    vec3 rdC = mix(p_rdGap, p_rdColour * p_rdEdge, rdEdge);
    rdC = mix(rdC, p_rdTubeColour, rdT);
    float rdD = p_rdDust * smoothstep(0.45, 0.85, kfbm4(uv * 5.0 + seed + 2.0) + 0.15 * kn(uv * 80.0 + seed));
    rdC = mix(rdC, p_rdDustColour * (0.7 + 0.5 * rdEdge), rdD * rdFin);
    k.colour = rdC;
    k.metal = p_rdMetal * (0.5 + 0.5 * rdT);
    k.rough = clamp(p_rdRough + 0.25 * rdFin * (1.0 - rdEdge) + 0.3 * rdD * rdFin, 0.05, 1.0);
    k.height = -p_rdDepth * rdFin * (1.0 - 0.6 * rdEdge);
    k.ao = 1.0 - 0.7 * rdFin * (1.0 - rdEdge) * rdFoldsSeen;
    k.aoDirect = 0.6;

}



void look_17(inout Look k, int lookRow) {
  p_bmColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_bmLines = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_bmStreak = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_bmLong = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_bmRough = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_bmMetal = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_bmRelief = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_bmMirror = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_bmSky = texelFetch(lookSettings, ivec2(8, lookRow), 0).rgb;
  p_bmWall = texelFetch(lookSettings, ivec2(9, lookRow), 0).rgb;
  p_bmFloor = texelFetch(lookSettings, ivec2(10, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 bmG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the brushing, across it
    vec2 bmQ = vec2(dot(uv, bmG), dot(uv, vec2(-bmG.y, bmG.x)));
    // the scratches: noise stretched far along the brushing, one row a scratch, faded to its mean where a scratch is
    // under a pixel; a few deeper, longer ones over them
    float bmFine = mix(0.5, kn(vec2(bmQ.x * p_bmLong * 4.0, bmQ.y * p_bmLines) + seed), kfade(2.0 / p_bmLines));
    float bmDeep = mix(0.5, kn(vec2(bmQ.x * p_bmLong, bmQ.y * p_bmLines * 0.18) + seed + 17.0), kfade(8.0 / p_bmLines));
    float bmS = 0.75 * bmFine + 0.25 * smoothstep(0.35, 0.8, bmDeep);
    // a slow cloud of the belt's passes, so a big sheet isn't one flat grey
    float bmPass = kfbm4(vec2(bmQ.x * 0.6, bmQ.y * 7.0) + seed * 1.3);
    vec3 bmC = p_bmColour * (1.0 + p_bmStreak * (bmS - 0.5) * 0.9) * (0.94 + 0.12 * bmPass);
    k.colour = bmC;
    k.metal = p_bmMetal;
    k.rough = clamp(p_bmRough + 0.12 * (bmS - 0.5) + 0.05 * (bmPass - 0.5), 0.03, 1.0);
    k.height = p_bmRelief * (bmS - 0.5);
    // the room mirrored, smeared along the brushing: its ray tipped across the scratches by each one's slope
    vec3 bmV = normalize(wp - cameraPosition);
    vec3 bmN = normalize(wn);
    vec3 bmR = reflect(bmV, bmN);
    float bmCos = clamp(dot(-bmV, bmN), 0.0, 1.0);
    float bmFres = 0.7 + 0.3 * pow(1.0 - bmCos, 3.0);
    vec3 bmRoom = rmRoom(normalize(bmR + 0.08 * (bmS - 0.5) * vec3(1.0, 0.0, 1.0)), clamp(p_bmRough * 2.2, 0.0, 1.0), p_bmSky, p_bmWall, p_bmFloor);
    k.glow = p_bmMirror * bmRoom * bmC * bmFres * (0.85 + 0.3 * bmS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(0.5 + 0.5 * bmG.x, 0.5 + 0.5 * bmG.y, 0.5);

}


void look_19(inout Look k, int lookRow) {
  p_pmColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_pmPeel = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_pmRelief = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_pmRough = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_pmCoat = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_pmCoatRough = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_pmOil = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_pmOilColour = texelFetch(lookSettings, ivec2(7, lookRow), 0).rgb;
  p_pmOilStreaks = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_pmOilRough = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_20(inout Look k, int lookRow) {
  p_clColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_clRub = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_clGrain = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_clGrainDepth = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_clCreases = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_clCrease = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_clWear = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_clRough = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_clRubRough = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_clCoat = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_clSheen = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the pebbled grain: cells pressed into the hide, high in their middles, furrowed at their edges
    float clId, clE;
    kvor(uv * p_clGrain + seed, clId, clE);
    float clSee = kfade(2.0 / p_clGrain);
    float clPeb = mix(0.7, smoothstep(0.0, 0.25, clE), clSee);
    float clCell = (kh1(clId) - 0.5) * clSee;
    // the dye's mottle over the hide
    float clMott = kfbm4(uv * 6.0 + seed);
    // soft creases: thin lines wandering every way over the hide where it bends (the contours of a slow noise), each
    // its own strength, some stretches with none
    float clN = kfbm(uv * p_clCreases * 0.3 + seed + 4.0);
    float clCr = (1.0 - smoothstep(0.0, 0.035, abs(clN - 0.5))) * smoothstep(0.4, 0.7, kfbm(uv * 3.0 + seed + 11.0));
    clCr *= p_clCrease * kfade(0.2 / p_clCreases);
    // the rubbing: the hide's own wear in patches, and the kind's hint where it is sat on or gripped
    float clRubA = clamp(p_clWear * smoothstep(0.5, 0.85, kfbm4(uv * 4.0 + seed + 2.0)) + s0.x, 0.0, 1.0);
    vec3 clC = p_clColour * (0.92 + 0.16 * clMott) * (1.0 + 0.035 * clCell);
    clC *= 0.94 + 0.06 * clPeb;
    clC = mix(clC, p_clRub, clRubA * 0.6);
    clC *= 1.0 - 0.18 * clCr;
    k.colour = clC;
    // rubbed smooth: the grain worn flatter and glossier where the hide is rubbed
    k.rough = clamp(mix(p_clRough, p_clRubRough, clRubA) + 0.08 * (1.0 - clPeb), 0.0, 1.0);
    k.height = p_clGrainDepth * clPeb * (1.0 - 0.6 * clRubA) - 0.0004 * clCr;
    k.ao = mix(0.85, 1.0, clPeb);
    k.clearcoat = p_clCoat;
    k.clearcoatRough = 0.35;
    k.sheen = mix(p_clColour, vec3(1.0), 0.5) * p_clSheen;
    k.sheenRough = 0.5;

}

void look_21(inout Look k, int lookRow) {
  p_cpColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_cpColour2 = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_cpTuft = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_cpFleck = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_cpCrush = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_cpRelief = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_cpSheen = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float cpF = kfade(p_cpTuft * 1.5);
    // the tufts' tips: two sizes of noise, the coarse the tufts, the fine the fibres at their tips
    float cpT = kn(uv / p_cpTuft + seed);
    float cpT2 = kn(uv / (p_cpTuft * 0.45) + seed * 3.1);
    float cpTip = mix(0.5, 0.6 * cpT + 0.4 * cpT2, cpF);
    // flecks of the second yarn, a tuft or two across
    float cpFl = mix(0.2, smoothstep(0.62, 0.8, kn(uv / (p_cpTuft * 0.8) + seed * 7.0)), cpF);
    // the pile crushed in soft patches
    float cpCr = kfbm4(uv * 2.5 + seed);
    vec3 cpC = mix(p_cpColour, p_cpColour2, p_cpFleck * cpFl);
    cpC *= (1.0 - p_cpCrush * 0.5) + p_cpCrush * cpCr;
    cpC *= 0.85 + 0.3 * cpTip;
    k.colour = cpC;
    k.rough = 0.97;
    k.height = p_cpRelief * cpTip;
    k.ao = mix(0.8, 1.0, cpTip);
    k.sheen = mix(p_cpColour, vec3(1.0), 0.35) * p_cpSheen;
    k.sheenRough = 0.6;

}

void look_22(inout Look k, int lookRow) {
  p_upKind = texelFetch(lookSettings, ivec2(0, lookRow), 0).r;
  p_upColour = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_upColour2 = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_upThread = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_upFleck = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_upPrint = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_upMotif = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_upRelief = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_upSheen = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_upRough = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // a loop's or a thread's own detail (its ring, its crossing) is half of it across: faded out before it aliases
    float upF = kfade(p_upThread * 0.5);
    vec2 cl = upCloth(uv, p_upKind, p_upThread, seed);
    float h = mix(0.5, cl.x, upF);
    float lite = mix(0.5, cl.y, upF);
    // heather: fibres of the second colour twisted into the yarn, finer than a thread
    float fleck = smoothstep(0.55, 0.85, kn(uv / (p_upThread * 0.7) + seed * 3.0));
    float fleckMean = 0.18;
    float heather = p_upFleck * mix(fleckMean, fleck, kfade(p_upThread * 0.7));
    vec3 col = mix(p_upColour, p_upColour2, heather);
    // the dye's slow unevenness over the cloth
    col *= 0.94 + 0.1 * kfbm4(uv * 4.0 + seed);
    // the print: leaves in the second colour, then the weave over it
    float leaf = upLeaf(uv, p_upMotif, seed) * kfade(p_upMotif * 0.2);
    float leafMean = 0.12;
    col = mix(col, p_upColour2, p_upPrint * mix(leafMean, leaf, kfade(p_upMotif * 0.2)));
    // low places in shadow of the yarn round them, high places catch the light; a mesh's holes dark
    // (a loop pile, bouclé or terry, is soft: its loops shade one another only a little)
    bool upLoops = (p_upKind > 1.5 && p_upKind < 2.5) || (p_upKind > 3.5 && p_upKind < 4.5);
    float shade = p_upKind > 2.5 && p_upKind < 3.5 ? mix(0.25, 1.0, h) : upLoops ? 0.88 + 0.15 * h : 0.78 + 0.3 * h;
    col *= shade * (upLoops ? 0.95 + 0.07 * lite : 0.92 + 0.12 * lite);
    // a loop pile's yarn bunches: clumps of loops a few loops across, standing proud or sinking, seen from across a room
    float clump = upLoops ? kfbm4(uv / (p_upThread * 3.0) + seed) : 0.5;
    float clumpF = kfade(p_upThread * 1.5);
    clump = mix(0.5, clump, clumpF);
    col *= 0.86 + 0.28 * clump;
    h = mix(h, clump, upLoops ? 0.6 : 0.0);
    k.colour = col;
    k.rough = p_upRough;
    k.height = p_upRelief * h;
    k.ao = mix(0.75, 1.0, h);
    k.sheen = mix(p_upColour, vec3(1.0), 0.35) * p_upSheen;
    k.sheenRough = 0.7;

}

void look_23(inout Look k, int lookRow) {
  p_gfFace = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_gfMark = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_gfRed = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_gfRadius = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_gfTicks = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_gfSweep = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_gfRead = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_gfNeedle = texelFetch(lookSettings, ivec2(7, lookRow), 0).rgb;
  p_gfGlow = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_gfTachSteps = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_gfTachRed = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_gfNumerals = texelFetch(lookSettings, ivec2(11, lookRow), 0).r;
  p_gfSpeedTop = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  p_gfSpeedStep = texelFetch(lookSettings, ivec2(13, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 gfP;
    float gfRad, gfKind, gfReadAt;
    if (s2.x > 0.001) {
      gfRad = s2.x * 0.5;
      gfP = s3 / gfRad;
      gfKind = floor(s2.z + 0.5);
      gfReadAt = clamp(s2.w, 0.0, 1.0);
    } else {
      gfRad = p_gfRadius;
      gfP = uv / gfRad;
      gfKind = 0.0;
      gfReadAt = p_gfRead;
    }
    if (gfKind > 8.5 || gfKind < -0.5) gfKind = 0.0;
    if (gfKind > 2.5 && gfKind < 3.5) {
      // a warning lamp, unlit: its lens's colour by s2.w, deep and dark; the bulb behind it a faint brightening in its
      // middle; the frame's shadow round its square edge
      float gfWhich = floor(s2.w + 0.5);
      vec3 gfLens = gfWhich < 0.5 ? vec3(0.09, 0.006, 0.004) : gfWhich < 1.5 ? vec3(0.1, 0.045, 0.003) :
                    gfWhich < 2.5 ? vec3(0.008, 0.06, 0.012) : vec3(0.006, 0.02, 0.09);
      vec2 gfSq = abs(gfP);
      float gfEdge = max(gfSq.x, gfSq.y);
      float gfEw = fwidth(gfEdge) + 0.002;
      float gfBulb = 1.0 - smoothstep(0.0, 0.75, length(gfP));
      vec3 gfL = gfLens * (0.7 + 0.6 * gfBulb);
      gfL *= 1.0 - 0.6 * smoothstep(0.78 - gfEw, 0.95, gfEdge);
      k.colour = gfL;
      k.metal = 0.0;
      k.rough = 0.25;
      k.glow = vec3(0.0);
    } else {
    bool gfSmall = gfKind > 1.5;
    float gfR = length(gfP);
    float gfE = fwidth(gfR) * 0.75 + 0.002;
    // the angle from straight up, degrees, clockwise; the sweep is centred on straight up
    float gfA = degrees(atan(gfP.x, gfP.y));
    float gfSw = gfSmall ? 90.0 : p_gfSweep;
    float gfHalf = gfSw * 0.5;
    float gfFrom = gfA + gfHalf;
    float gfIn = step(-0.5, gfFrom) * step(gfFrom, gfSw + 0.5);
    float gfInk = 0.0;
    float gfRedInk = 0.0;
    float gfNumInk = 0.0;
    float gfNe = fwidth(gfP.x) + fwidth(gfP.y);
    bool gfNum = p_gfNumerals > 0.5;
    if (gfKind < 0.5) {
      float gfStep = gfSw / p_gfTicks;
      gfInk = gfIn * max(gfRing(gfFrom, gfStep, gfR, 0.8, 0.93, 0.012, gfE), gfRing(gfFrom, gfStep * 5.0, gfR, 0.68, 0.93, 0.024, gfE));
      if (gfNum) {
        float gfCount = floor(p_gfSpeedTop / p_gfSpeedStep + 0.5);
        for (int i = 0; i <= 40; i++) {
          if (float(i) > gfCount) break;
          float v = float(i) * p_gfSpeedStep;
          gfNumInk = max(gfNumInk, gfNumber(gfP, gfAt(gfSw * v / p_gfSpeedTop, gfSw, 0.52, vec2(0.0)), v, 0.11, gfNe));
        }
      }
    } else if (gfKind < 1.5) {
      // gfTachSteps steps of 500 rpm, long at each thousand; red from gfTachRed of the sweep, with a red arc inside
      // the marks
      float gfStep = gfSw / p_gfTachSteps;
      float gfMarks = gfIn * max(gfRing(gfFrom, gfStep, gfR, 0.8, 0.93, 0.014, gfE), gfRing(gfFrom, gfStep * 2.0, gfR, 0.68, 0.93, 0.026, gfE));
      float gfHot = step(gfSw * p_gfTachRed, gfFrom) * gfIn;
      float gfArc = gfHot * smoothstep(0.62 - gfE, 0.62, gfR) * (1.0 - smoothstep(0.68, 0.68 + gfE, gfR));
      gfInk = gfMarks * (1.0 - gfHot);
      gfRedInk = max(gfMarks * gfHot, gfArc);
      if (gfNum) {
        float gfTop = p_gfTachSteps * 0.5;
        for (int i = 0; i <= 12; i++) {
          if (float(i) > gfTop) break;
          gfNumInk = max(gfNumInk, gfNumber(gfP, gfAt(gfSw * float(i) / gfTop, gfSw, 0.48, vec2(0.0)), float(i), 0.15, gfNe));
        }
      }
    } else {
      // three long marks over the top arc, two short between; the low end's red
      float gfMarks = gfIn * max(gfRing(gfFrom, gfSw / 4.0, gfR, 0.72, 0.92, 0.03, gfE), gfRing(gfFrom, gfSw / 2.0, gfR, 0.56, 0.92, 0.05, gfE));
      float gfLow = step(gfFrom, gfSw * 0.12);
      gfInk = gfMarks * (1.0 - gfLow);
      gfRedInk = gfMarks * gfLow;
      if (gfNum && gfKind > 3.5) {
        // its three numerals inside the arc's ends and middle, about the needle's pivot low on the face
        vec3 gfVals = gfKind < 4.5 ? vec3(0.0, 1.0, 2.0) : gfKind < 5.5 ? vec3(0.0, 5.0, 10.0) :
                      gfKind < 6.5 ? vec3(40.0, 80.0, 120.0) : gfKind < 7.5 ? vec3(50.0, 100.0, 150.0) :
                      vec3(0.0, -1.0, 1.0);
        float gfSz = gfVals.z > 99.5 ? 0.17 : 0.2;
        for (int i = 0; i < 3; i++) {
          float v = gfVals[i];
          if (v < -0.5) continue;
          vec2 c = vec2(sin(radians(-48.0 + 48.0 * float(i))), cos(radians(-48.0 + 48.0 * float(i)))) * 0.52;
          c.y -= 0.14;
          gfNumInk = max(gfNumInk, gfNumber(gfP, c, v, gfSz, gfNe));
        }
      }
    }
    // the numerals finer than a pixel fade out
    gfNumInk *= kfade(0.1 * gfRad);
    gfInk = max(gfInk, gfNumInk);
    // the needle from just behind the hub out to the marks, tapering; a small gauge's pivots low, its needle long
    float gfAn = radians(-gfHalf + gfSw * gfReadAt);
    vec2 gfDir = vec2(sin(gfAn), cos(gfAn));
    vec2 gfQ = gfSmall ? gfP + vec2(0.0, 0.55) : gfP;
    float gfLen = gfSmall ? 1.3 : 0.8;
    float gfAlong = clamp(dot(gfQ, gfDir), -0.15, gfLen);
    float gfOff = length(gfQ - gfDir * gfAlong);
    float gfWide = 0.04 * (1.0 - 0.6 * max(gfAlong, 0.0) / gfLen);
    float gfNeedle = 1.0 - smoothstep(gfWide, gfWide + gfE, gfOff);
    gfNeedle *= step(length(gfP), 0.98);
    float gfHub = 1.0 - smoothstep(0.1, 0.1 + gfE, length(gfQ));
    gfHub *= step(length(gfP), 0.98);
    vec3 gfC = mix(p_gfFace, p_gfMark, clamp(gfInk, 0.0, 1.0));
    gfC = mix(gfC, p_gfRed, clamp(gfRedInk, 0.0, 1.0));
    gfC = mix(gfC, p_gfNeedle, gfNeedle);
    gfC = mix(gfC, vec3(0.02), gfHub);
    // finer than a pixel, the dial is the grey its marks make; and the bezel's shadow at its rim
    float gfF = kfade(0.1 * gfRad);
    gfC = mix(mix(p_gfFace, p_gfMark, 0.1), gfC, gfF);
    gfC *= 1.0 - 0.55 * smoothstep(0.9, 1.0, gfR);
    k.colour = gfC;
    k.metal = 0.0;
    k.rough = 0.5;
    k.glow = (p_gfMark * clamp(gfInk, 0.0, 1.0) + p_gfRed * clamp(gfRedInk, 0.0, 1.0) + p_gfNeedle * gfNeedle) * p_gfGlow * gfF * (1.0 - gfHub);
    }

}




void look_28(inout Look k, int lookRow) {
  p_rmColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_rmWorn = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_rmDirt = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_rmDirtAmount = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_rmRibs = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_rmDepth = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_rmRough = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float rmSee = kfade(2.0 / p_rmRibs);
    float rmT = fract(uv.y * p_rmRibs);
    float rmRib = smoothstep(0.15, 0.3, rmT) * (1.0 - smoothstep(0.7, 0.85, rmT));
    float rmR = mix(0.5, rmRib, rmSee);
    float rmD = p_rmDirtAmount * (1.0 - rmR) * smoothstep(0.3, 0.8, kfbm4(uv * 5.0 + seed));
    k.colour = mix(p_rmColour, p_rmWorn, rmR * 0.6 * kfbm4(uv * 12.0 + seed + 3.0));
    k.colour = mix(k.colour, p_rmDirt, clamp(rmD * 1.6, 0.0, 1.0));
    k.rough = clamp(p_rmRough - 0.15 * rmR + 0.1 * rmD, 0.0, 1.0);
    k.height = p_rmDepth * rmR;

}


void look_30(inout Look k, int lookRow) {
  p_lpColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_lpBack = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_lpReflector = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_lpCellW = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_lpCellH = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_lpFlute = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_lpDepth = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_lpTwinkle = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_lpGlow = texelFetch(lookSettings, ivec2(8, lookRow), 0).rgb;
  p_lpSpot = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_lpSpotSize = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 lpQ = uv / vec2(p_lpCellW, p_lpCellH);
    vec2 lpId = floor(lpQ);
    vec2 lpF = fract(lpQ) - 0.5;
    // the prisms seen only where one is bigger than a pixel; under that, their mean
    float lpSee = kfade(min(p_lpCellW, p_lpCellH) * 1.5);
    // each prism's swell: 1 in its middle, 0 at its rim; a flute swells across only
    float lpAcross = 1.0 - 4.0 * lpF.x * lpF.x;
    float lpUp = mix(1.0 - 4.0 * lpF.y * lpF.y, 1.0, p_lpFlute);
    float lpBump = lpAcross * lpUp;
    // the thin line where two prisms meet (a flute's only between flutes)
    float lpRim = max(abs(lpF.x), abs(lpF.y) * (1.0 - p_lpFlute));
    float lpEdge = smoothstep(0.43, 0.5, lpRim) * lpSee;
    float lpTone = mix(1.0, 1.0 + p_lpTwinkle * (kh(lpId + seed) - 0.5), lpSee);
    // the reflector behind, through each prism's middle, brightest looked at straight on
    float lpFace = clamp(dot(normalize(cameraPosition - wp), normalize(wn)), 0.0, 1.0);
    float lpRef = p_lpReflector * lpFace * lpFace * mix(0.55, 0.25 + 0.9 * lpBump, lpSee) * lpTone;
    k.colour = p_lpColour * mix(1.0, 0.8 + 0.35 * lpBump, lpSee) * lpTone * (1.0 - 0.45 * lpEdge) + p_lpBack * lpRef;
    k.metal = 0.0;
    k.rough = 0.04 + 0.12 * lpEdge;
    k.height = p_lpDepth * lpBump * lpSee;
    k.clearcoat = 1.0;
    k.clearcoatRough = 0.03;
    // lit: the lamp's light out of the glass, round the bulb and through each prism's middle
    float lpHot = exp(-dot(uv, uv) / (p_lpSpotSize * p_lpSpotSize));
    float lpLit = (1.0 - p_lpSpot) + p_lpSpot * 2.0 * lpHot;
    k.glow = p_lpGlow * lpLit * mix(1.0, 0.65 + 0.55 * lpBump, lpSee) * lpTone * (1.0 - 0.5 * lpEdge);

}




void look_34(inout Look k, int lookRow) {
  p_rrColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_rrReturn = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_rrTight = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_rrCell = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_rrSeal = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_rrRelief = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_rrPrism = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_rrGlitter = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_rrRough = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_rrCoat = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_rrCoatRough = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the seal net: a regular net of diamond cells (the sheeting's grid turned 45 degrees), their edges the darker
    // seal lines
    vec2 rrD = vec2(uv.x + uv.y, uv.x - uv.y) * 0.7071 / p_rrCell;
    vec2 rrCellId = floor(rrD);
    vec2 rrF = abs(fract(rrD) - 0.5);
    float rrEdge = 0.5 - max(rrF.x, rrF.y);
    float rrNetF = kfade(p_rrCell * 0.15);
    float rrLine = (1.0 - smoothstep(0.02, 0.06, rrEdge)) * rrNetF;
    // the prisms: a fine glitter, each prism a cell of its own brightness, faded to its mean far off
    float rrPF = kfade(2.0 / p_rrPrism);
    float rrP = mix(0.5, kh(floor(uv * p_rrPrism) + seed), rrPF);
    // each seal cell its own slight tone, as the sheeting's cells catch the light a little differently
    float rrTone = 0.96 + 0.08 * kh(rrCellId + seed);
    vec3 rrFace = p_rrColour * rrTone * (1.0 - p_rrSeal * rrLine);
    k.colour = rrFace * (1.0 + p_rrGlitter * (rrP - 0.5));
    // the light sent back to the eye: strongest square on, none along the face, none from a seal line
    float rrFacing = clamp(dot(normalize(cameraPosition - wp), normalize(wn)), 0.0, 1.0);
    float rrBack = pow(rrFacing, p_rrTight);
    k.glow = p_rrReturn * rrBack * rrTone * (1.0 - p_rrSeal * rrLine) * (1.0 + p_rrGlitter * (rrP - 0.5));
    k.rough = clamp(p_rrRough + 0.3 * rrLine, 0.0, 1.0);
    k.clearcoat = p_rrCoat;
    k.clearcoatRough = p_rrCoatRough;
    k.height = p_rrRelief * (1.0 - rrLine) * rrNetF;

}




void look_39(inout Look k, int lookRow) {
  p_ucColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
