  p_ucDustColour = texelFetch(lookSettings, ivec2(5, lookRow), 0).rgb;
  p_ucChips = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_ucRust = texelFetch(lookSettings, ivec2(7, lookRow), 0).rgb;
  p_ucOil = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float ucDown = smoothstep(0.0, -0.8, wn.y);
    float ucUp = smoothstep(0.3, 0.95, wn.y);
    float ucB = kfbm(uv * 4.0 + seed);
    float ucG = clamp(p_ucGrime * (0.3 + 0.9 * ucDown) * smoothstep(0.3, 0.75, ucB + 0.25 * ucDown), 0.0, 1.0);
    float ucD = clamp(p_ucDust * ucUp * smoothstep(0.35, 0.8, kfbm4(uv * 7.0 + seed + 4.0)), 0.0, 1.0);
    // chips gather in patches (a slow field) and are each a small blot (a fast one), so they cluster on a part
    float ucPatch = smoothstep(0.55, 0.8, kfbm4(uv * 1.5 + seed + 21.0));
    float ucChipN = (kn(uv * 70.0 + seed + 9.0) + 0.15 * kn(uv * 300.0 + seed)) * kfade(0.02);
    float ucChip = ucPatch * smoothstep(1.06 - 0.12 * p_ucChips, 1.1 - 0.12 * p_ucChips, ucChipN);
    float ucO = p_ucOil * smoothstep(0.55, 0.85, kfbm4(uv * 2.0 + seed + 11.0));
    k.colour = mix(p_ucColour, p_ucGrimeColour, ucG);
    k.colour = mix(k.colour, p_ucDustColour, ucD);
    k.colour = mix(k.colour, p_ucRust * (0.7 + 0.6 * kn(uv * 200.0 + seed)), ucChip);
    k.colour = mix(k.colour, vec3(0.01, 0.008, 0.006), ucO);
    k.rough = clamp(p_ucRough + 0.35 * ucG + 0.3 * ucD + 0.35 * ucChip - 0.4 * ucO, 0.05, 1.0);
    k.metal = 0.0;
    k.height = 0.00015 * ucG * ucB - 0.0001 * ucChip;

}



void look_42(inout Look k, int lookRow) {
  p_gvColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_gvSpangle = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_gvTone = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_gvRough = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_gvRoughVar = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_gvBloom = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_gvMetal = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_gvRelief = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float gvId, gvE;
    vec2 gvP = uv * p_gvSpangle + seed * 11.0;
    gvP += vec2(kn(uv * 9.0 + seed), kn(uv * 9.0 + seed + 4.0)) * 0.6;
    kvor(gvP, gvId, gvE);
    float gvF = kfade(1.5 / p_gvSpangle);
    // the dendrites: fine lines along the crystal's own angle
    float gvA = gvId * 6.2832;
    vec2 gvDir = vec2(cos(gvA), sin(gvA));
    float gvDen = abs(sin(dot(uv, gvDir) * p_gvSpangle * 40.0 + kn(uv * p_gvSpangle * 6.0) * 3.0));
    gvDen = smoothstep(0.6, 1.0, gvDen) * kfade(0.8 / (p_gvSpangle * 12.0)) * gvF;
    float gvB = smoothstep(0.45, 0.8, kfbm4(uv * 2.5 + seed + 2.0)) * p_gvBloom;
    float gvT = (gvId - 0.5) * 2.0 * p_gvTone * gvF;
    vec3 c = p_gvColour * (1.0 + gvT) * (1.0 - 0.06 * gvDen);
    c = mix(c, vec3(0.56, 0.56, 0.55), gvB);
    k.colour = c;
    k.metal = mix(p_gvMetal, 0.3, gvB);
    k.rough = clamp(p_gvRough + p_gvRoughVar * (kh1(gvId * 17.0) - 0.5) * 2.0 * gvF + 0.08 * gvDen + 0.3 * gvB, 0.05, 1.0);
    k.height = p_gvRelief * (smoothstep(0.03, 0.0, gvE) * gvF + 0.5 * gvDen);

}










void look_52(inout Look k, int lookRow) {
  p_apColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_apFlake = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_apFlakeColour = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_apFlakeSize = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_apRough = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_apCoat = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_apCoatRough = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_apPeel = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_apPeelDepth = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_apDust = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_apDustColour = texelFetch(lookSettings, ivec2(10, lookRow), 0).rgb;
  p_apDustHeight = texelFetch(lookSettings, ivec2(11, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // flake: one fleck a cell, each its own brightness and its own tilt, fading to its mean where a fleck is under a pixel
    vec2 apC = floor(uv / p_apFlakeSize);
    float apS = kh(apC + seed);
    float apSee = kfade(p_apFlakeSize * 3.0);
    float apFleck = mix(0.5, step(0.55, apS) * (0.4 + 0.6 * kh(apC + seed + 17.0)), apSee) * p_apFlake;
    vec3 apBase = p_apColour * (0.97 + 0.06 * kfbm4(uv * 1.5 + seed));
    k.colour = mix(apBase, apBase * 0.4 + p_apFlakeColour * 0.6, apFleck * 0.35);
    k.metal = p_apFlake * 0.6;
    k.rough = clamp(p_apRough - 0.15 * apFleck, 0.0, 1.0);
    float apPeelF = kfade(2.0 / p_apPeel);
    float apP = (1.0 - kcell(uv * p_apPeel + seed)) * apPeelF;
    k.height = p_apPeelDepth * apP + 0.000004 * (apS - 0.5) * apSee * p_apFlake;
    k.clearcoat = p_apCoat;
    k.clearcoatRough = p_apCoatRough;
    // road dust: thick at the ground, gone by apDustHeight, broken up so it reads as spray, not a band
    float apLow = 1.0 - smoothstep(0.0, p_apDustHeight, wp.y);
    float apSpray = smoothstep(0.25, 0.85, kfbm(uv * 6.0 + seed + 3.0) + 0.35 * apLow);
    float apD = clamp(p_apDust * apLow * apSpray * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_apDustColour * (0.85 + 0.3 * kn(uv * 60.0 + seed)), apD);
    k.rough = mix(k.rough, 0.85, apD);
    k.metal = mix(k.metal, 0.0, apD);
    k.clearcoat = mix(k.clearcoat, 0.0, apD);

}

void look_53(inout Look k, int lookRow) {
