    vec3 vcV = normalize(cameraPosition - wp);
    float vcFace = clamp(abs(dot(vcV, normalize(wn))), 0.0, 1.0);
    float vcCl = kfbm(uv * 6.0 + seed) - 0.5;
    vec3 vcC = p_vcColour * (1.0 + p_vcCloud * vcCl * 2.0);
