    vcC = mix(vcC, pow(max(vcC, vec3(0.0)), vec3(1.15)) * 1.1, p_vcRich * vcFace);
    k.colour = vcC;
    k.rough = p_vcRough;
    k.metal = 0.0;
    k.height = p_vcPeel * mix(0.0, kn(uv * 180.0 + seed), kfade(0.004));
    k.clearcoat = 1.0;
    k.clearcoatRough = p_vcCoatRough;

}








void look_78(inout Look k, int lookRow) {
  p_cdDark = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_cdLight = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_cdLay = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_cdRound = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_cdRough = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_cdCoat = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_cdRelief = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // three strands round its girth, each leaning along its lay
    float cdT = fract(uv.x / p_cdLay + uv.y * 3.0 / p_cdRound);
    float cdS = smoothstep(0.0, 0.3, cdT) * smoothstep(1.0, 0.7, cdT);
    float cdF = kn(vec2(uv.x * 900.0 + uv.y * 300.0, uv.y * 120.0) + seed) * kfade(0.0015);
    float cdV = kfade(p_cdLay * 0.5);
    float cdM = mix(0.5, cdS, cdV);
    k.colour = mix(p_cdDark, p_cdLight, cdM) * (0.88 + 0.24 * cdF) * (0.9 + 0.2 * kfbm(uv * 20.0 + seed));
    k.rough = p_cdRough;
    k.clearcoat = p_cdCoat * cdM;
    k.clearcoatRough = 0.35;
    k.height = p_cdRelief * cdM;

}





void look_83(inout Look k, int lookRow) {
  p_erScale = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_erRustColour = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_erRustDark = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_erBakeColour = texelFetch(lookSettings, ivec2(3, lookRow), 0).rgb;
  p_erDustColour = texelFetch(lookSettings, ivec2(4, lookRow), 0).rgb;
  p_erPatches = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_erRust = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_erBake = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_erDust = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_erSoot = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_erGrain = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_erRelief = texelFetch(lookSettings, ivec2(11, lookRow), 0).r;
  p_erRough = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  p_erMetal = texelFetch(lookSettings, ivec2(13, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float erG = mix(0.5, kn(uv * p_erGrain + seed), kfade(2.0 / p_erGrain));
    float erG2 = mix(0.5, kn(uv * p_erGrain * 0.31 + seed + 4.0), kfade(5.0 / p_erGrain));
    float erDown = smoothstep(0.2, -0.8, wn.y);
    float erUp = smoothstep(0.2, 0.9, wn.y);
    // rust: blooms through the scale, more on the undersides, a ragged edge where the scale flakes
    float erF = kfbm4(uv * p_erPatches + seed + 2.0) + 0.25 * erDown + 0.15 * (erG2 - 0.5);
    float erR = p_erRust * smoothstep(0.42, 0.62, erF);
    float erEdge = smoothstep(0.38, 0.45, erF) * (1.0 - smoothstep(0.45, 0.55, erF)) * kfade(3.0 / p_erGrain);
    vec3 erC = p_erScale * (0.85 + 0.3 * erG);
    vec3 erRc = mix(p_erRustDark, p_erRustColour, smoothstep(0.3, 0.8, kfbm(uv * p_erPatches * 5.0 + seed + 8.0)));
    erC = mix(erC, erRc * (0.85 + 0.3 * erG), erR);
    // baked dark where it ran hottest
    float erB = p_erBake * smoothstep(0.45, 0.8, kfbm(uv * p_erPatches * 0.5 + seed + 13.0));
    erC = mix(erC, p_erBakeColour, erB * (1.0 - 0.5 * erR));
    // soot in drifts, road dust on the tops
    float erS = p_erSoot * smoothstep(0.5, 0.85, kfbm(uv * p_erPatches * 1.7 + seed + 21.0));
    erC = mix(erC, vec3(0.012, 0.011, 0.01), erS);
    float erD = p_erDust * erUp * smoothstep(0.35, 0.7, kfbm(uv * p_erPatches * 2.0 + seed + 31.0));
    erC = mix(erC, p_erDustColour, erD);
    k.colour = erC;
    k.metal = p_erMetal * (1.0 - erR) * (1.0 - erD) * (1.0 - erS);
    k.rough = clamp(p_erRough + 0.1 * (erG - 0.5) + 0.08 * erR + 0.1 * erD - 0.1 * erB, 0.2, 1.0);
    k.height = p_erRelief * (0.5 * (erG - 0.5) + 0.4 * erR * (erG2 - 0.5) + 1.2 * erEdge);
    k.ao = 1.0 - 0.25 * erEdge;

}











void look_94(inout Look k, int lookRow) {
  p_bhColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_bhGap = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_bhBands = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_bhWires = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_bhRelief = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_bhRough = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_bhMetal = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_bhGrime = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_bhGrimeColour = texelFetch(lookSettings, ivec2(8, lookRow), 0).rgb;
  p_bhMirror = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_bhSky = texelFetch(lookSettings, ivec2(10, lookRow), 0).rgb;
  p_bhWall = texelFetch(lookSettings, ivec2(11, lookRow), 0).rgb;
  p_bhFloor = texelFetch(lookSettings, ivec2(12, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the two helices: coordinates along each band's way, a band every 1/bhBands across it
    vec2 bhP = uv * p_bhBands;
    float bhA = bhP.x + bhP.y;
    float bhB = bhP.x - bhP.y;
    // a twill: band A over the other in two cells of four along its way, then under two
    float bhOver = 1.0 - step(1.5, mod(floor(bhB) - floor(bhA), 4.0));
    // across each band: its wires' crowns, and the band's own edges falling into the gap
    float bhFa = fract(bhA);
    float bhFb = fract(bhB);
    float bhWa = 0.5 + 0.5 * cos(6.2832 * bhFa * p_bhWires);
    float bhWb = 0.5 + 0.5 * cos(6.2832 * bhFb * p_bhWires);
    float bhEa = smoothstep(0.0, 0.08, bhFa) * (1.0 - smoothstep(0.92, 1.0, bhFa));
    float bhEb = smoothstep(0.0, 0.08, bhFb) * (1.0 - smoothstep(0.92, 1.0, bhFb));
    // the band on top here: its wires' crown, rising over the band beneath and dropping at the crossing's ends
    float bhLiftA = sin(3.1416 * fract(bhB));
    float bhLiftB = sin(3.1416 * fract(bhA));
    float bhTop = mix(bhEb * (0.55 + 0.45 * bhWb) * (0.6 + 0.4 * bhLiftB), bhEa * (0.55 + 0.45 * bhWa) * (0.6 + 0.4 * bhLiftA), bhOver);
    // fade the weave to its mean where a band is finer than a pixel, and the wires where they are
    float bhSeenBand = kfade(2.0 / p_bhBands);
    float bhH = mix(0.62, bhTop, bhSeenBand);
    float bhGr = p_bhGrime * smoothstep(0.35, 0.8, kfbm4(uv * 5.0 + seed + 3.0));
    vec3 bhC = mix(p_bhGap, p_bhColour, smoothstep(0.08, 0.6, bhH));
    bhC = mix(bhC, p_bhGrimeColour, bhGr * (0.4 + 0.6 * (1.0 - bhH)));
    k.colour = bhC;
    k.metal = p_bhMetal * smoothstep(0.05, 0.5, bhH) * (1.0 - 0.6 * bhGr);
    k.rough = clamp(p_bhRough + 0.3 * (1.0 - bhH) + 0.3 * bhGr, 0.05, 1.0);
    k.height = p_bhRelief * bhH;
    k.ao = 1.0 - 0.5 * (1.0 - bhH) * bhSeenBand;
    vec3 bhV = normalize(wp - cameraPosition);
    vec3 bhN = normalize(wn);
    vec3 bhRoom = rmRoom(reflect(bhV, bhN), clamp(p_bhRough * 1.8, 0.0, 1.0), p_bhSky, p_bhWall, p_bhFloor);
    k.glow = p_bhMirror * bhRoom * bhC * smoothstep(0.2, 0.8, bhH) * (1.0 - bhGr);

}




void look_98(inout Look k, int lookRow) {
  p_fcColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_fcCells = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_fcFine = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_fcDepth = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_fcFineDepth = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_fcTone = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_fcMetal = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_fcRough = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_fcSeam = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_fcTape = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_fcDust = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_fcDustColour = texelFetch(lookSettings, ivec2(11, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the creased facets: a pit in each cell, its rim the creases; and the finer crumple over it
    float fcId, fcEdge, fcId2, fcEdge2;
    vec2 fcP = uv * p_fcCells + seed * 13.0;
    float fcD = kvor(fcP, fcId, fcEdge);
    float fcD2 = kvor(fcP * p_fcFine + 5.1, fcId2, fcEdge2);
    float fcF = kfade(1.0 / p_fcCells), fcF2 = kfade(1.0 / (p_fcCells * p_fcFine));
    float fcH = (fcD * (0.6 + 0.8 * fcId) - 0.5) * fcF + p_fcFineDepth * (fcD2 - 0.5) * fcF2;
    // the tape over each seam, flat and duller
    float fcS = abs(fract(uv.y / p_fcSeam + 0.5) - 0.5) * p_fcSeam;
    float fcT = (1.0 - smoothstep(p_fcTape * 0.5 - 0.001, p_fcTape * 0.5, fcS)) * kfade(p_fcTape);
    float fcTone = 1.0 + p_fcTone * (fcId - 0.5) * 2.0 * fcF;
    vec3 fcC = p_fcColour * fcTone;
    fcC = mix(fcC, p_fcColour * 0.85, fcT);
    // dust: settled in a slow cloud, thicker in the pits
    float fcDu = clamp(p_fcDust * (0.5 + kfbm4(uv * 3.0 + seed + 2.0)) * (0.8 + 0.4 * fcD * fcF), 0.0, 1.0);
    k.colour = mix(fcC, p_fcDustColour, fcDu * 0.7);
    k.metal = mix(p_fcMetal, 0.0, fcDu * 0.7);
    k.rough = clamp(mix(p_fcRough + 0.08 * fcId2 * fcF2, 0.35, fcT) + fcDu * 0.6, 0.02, 1.0);
    k.height = p_fcDepth * fcH * (1.0 - fcT);

}







void look_105(inout Look k, int lookRow) {
  p_nfColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_nfColour2 = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_nfFibre = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_nfFleck = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_nfCloud = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_nfPill = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_nfRelief = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_nfSheen = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_nfRough = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the fuzz: two sizes of matted fibre, faded to their mean finer than a pixel
    float nfF = kfade(p_nfFibre * 2.0);
    float nfFuzz = mix(0.5, kfbm(uv / p_nfFibre + seed * 5.0), nfF);
    float nfOdd = smoothstep(0.62, 0.8, kn(uv / (p_nfFibre * 1.6) + seed * 11.0));
    nfOdd = mix(0.12, nfOdd, kfade(p_nfFibre * 1.6));
    vec3 nfCol = mix(p_nfColour, p_nfColour2, p_nfFleck * nfOdd);
    // the felt's density clouding over a hand's width, and its pills
    float nfCloudN = kfbm4(uv * 18.0 + seed);
    nfCol *= 1.0 + p_nfCloud * 0.4 * (nfCloudN - 0.5);
    float nfId, nfE;
    float nfD = kvor(uv / 0.004 + seed * 3.0, nfId, nfE);
    float nfPillM = (1.0 - smoothstep(0.08, 0.2, nfD)) * step(0.82, fract(nfId * 7.13)) * p_nfPill * kfade(0.002);
    nfCol *= 0.88 + 0.24 * nfFuzz + 0.15 * nfPillM;
    k.colour = nfCol;
    k.metal = 0.0;
    k.rough = p_nfRough;
    k.height = p_nfRelief * (nfFuzz + nfPillM * 1.5);
    k.ao = 0.85 + 0.15 * nfFuzz;
    k.sheen = mix(p_nfColour2, vec3(1.0), 0.3) * p_nfSheen;
    k.sheenRough = 0.85;

}


























































void look_164(inout Look k, int lookRow) {
  p_sbColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_sbCells = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_sbDepth = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_sbGlow = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_sbGlowColour = texelFetch(lookSettings, ivec2(4, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float sbSee = kfade(2.0 / p_sbCells);
    vec2 sbF = fract(uv * p_sbCells) - 0.5;
    float sbBump = (1.0 - dot(sbF, sbF) * 3.0) * sbSee;
    float sbFlute = (1.0 - smoothstep(0.38, 0.5, max(abs(sbF.x), abs(sbF.y)))) * sbSee;
    k.colour = p_sbColour * (0.85 + 0.15 * sbFlute);
    k.metal = 0.85;
    k.rough = 0.06 + 0.12 * (1.0 - sbFlute) * sbSee;
    k.height = p_sbDepth * sbBump;
    k.clearcoat = 1.0;
    k.clearcoatRough = 0.02;
    k.glow = p_sbGlowColour * p_sbGlow * (0.75 + 0.25 * sbFlute);

}

void look_165(inout Look k, int lookRow) {
  p_lnColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_lnGlow = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_lnSize = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_lnRings = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_lnRingAmount = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_lnFall = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_lnRelief = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 lnQ = (fract(uv / p_lnSize) - 0.5) * 2.0;
    float lnR = clamp(length(lnQ), 0.0, 1.0);
    // the rings, soft: a smooth wave in r, faded where a ring is finer than a pixel
    float lnRingF = kfade(p_lnSize * 0.5 / p_lnRings);
    float lnRing = (0.5 + 0.5 * cos(lnR * p_lnRings * 6.2832)) * lnRingF + 0.5 * (1.0 - lnRingF);
    float lnCore = 1.0 - p_lnFall * smoothstep(0.0, 1.0, lnR);
    float lnBand = 1.0 - p_lnRingAmount + p_lnRingAmount * 2.0 * lnRing * (1.0 - 0.5 * lnR);
    k.colour = p_lnColour;
    k.glow = p_lnGlow * lnCore * lnBand;
    k.rough = 0.06;
    k.height = p_lnRelief * lnRing * lnRingF;
    k.clearcoat = 0.3;
    k.clearcoatRough = 0.05;

}













void look_179(inout Look k, int lookRow) {
  p_cpGold = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_cpOlive = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_cpViolet = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_cpSilver = texelFetch(lookSettings, ivec2(3, lookRow), 0).rgb;
  p_cpBlotch = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_cpTint = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_cpWear = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_cpBloom = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_cpRough = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_cpMetal = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_cpFilm = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_cpMirror = texelFetch(lookSettings, ivec2(11, lookRow), 0).r;
  p_cpSky = texelFetch(lookSettings, ivec2(12, lookRow), 0).rgb;
  p_cpWall = texelFetch(lookSettings, ivec2(13, lookRow), 0).rgb;
  p_cpFloor = texelFetch(lookSettings, ivec2(14, lookRow), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the film's thickness, wandering in soft blotches with finer runs inside them
    float cpT = kfbm4(uv * p_cpBlotch + seed);
    float cpT2 = kfbm(uv * p_cpBlotch * 4.0 + seed + 3.0);
    float cpTh = clamp(cpT * 0.8 + cpT2 * 0.35 - 0.1, 0.0, 1.0);
    // thin to thick: olive, gold, bronze, violet
    vec3 cpC = mix(p_cpOlive, p_cpGold, smoothstep(0.15, 0.45, cpTh));
    cpC = mix(cpC, p_cpGold * vec3(0.95, 0.72, 0.5), smoothstep(0.5, 0.7, cpTh));
    cpC = mix(cpC, p_cpViolet, smoothstep(0.58, 0.8, cpTh));
    cpC = mix(p_cpSilver, cpC, p_cpTint);
    // worn through to the plate on the high spots
    float cpW = p_cpWear * smoothstep(0.62, 0.8, kfbm(uv * p_cpBlotch * 2.5 + seed + 9.0));
    cpC = mix(cpC, p_cpSilver, cpW);
    // the white salts and grime in patches
    float cpB = p_cpBloom * smoothstep(0.5, 0.85, kfbm4(uv * p_cpBlotch * 0.6 + seed + 17.0));
    cpC = mix(cpC, vec3(0.52, 0.5, 0.44), cpB);
    k.colour = cpC;
    k.metal = p_cpMetal * (1.0 - 0.6 * cpB);
    k.rough = clamp(p_cpRough + 0.1 * (cpT2 - 0.5) + 0.3 * cpB - 0.08 * cpW, 0.05, 1.0);
    k.iridescence = p_cpFilm * p_cpTint * (1.0 - cpW) * (1.0 - cpB);
    k.iridIor = 1.6;
    k.iridThick = 250.0 + 450.0 * cpTh;
    k.height = 0.000004 * (cpT2 - 0.5);
    vec3 cpV = normalize(wp - cameraPosition);
    vec3 cpN = normalize(wn);
    float cpCos = clamp(dot(-cpV, cpN), 0.0, 1.0);
    vec3 cpRoom = rmRoom(reflect(cpV, cpN), clamp(p_cpRough * 1.6, 0.0, 1.0), p_cpSky, p_cpWall, p_cpFloor);
    k.glow = p_cpMirror * cpRoom * cpC * (0.7 + 0.3 * pow(1.0 - cpCos, 3.0)) * (1.0 - cpB);

}
















void look_195(inout Look k, int lookRow) {
  p_wcKind = texelFetch(lookSettings, ivec2(0, lookRow), 0).r;
  p_wcColour = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_wcColour2 = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_wcColour3 = texelFetch(lookSettings, ivec2(3, lookRow), 0).rgb;
  p_wcRepeat = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_wcLine = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_wcThread = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_wcFleck = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_wcRelief = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_wcSheen = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_wcRough = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the cloth's own way: x across the stripes, y along them
    vec2 wcG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(0.0, 1.0);
