    col *= 0.94 + 0.1 * kfbm4(uv * 4.0 + seed);
    col *= 0.8 + 0.28 * h;
    k.colour = col;
    k.rough = p_wcRough;
    k.height = p_wcRelief * h;
    k.ao = mix(0.8, 1.0, h);
    k.sheen = mix(col, vec3(1.0), 0.35) * p_wcSheen;
    k.sheenRough = 0.65;

