void look_60(inout Look k, int lookRow) {
  p_ckCarbon = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_ckCarbonShine = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_ckAramid = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_ckAramidShine = texelFetch(lookSettings, ivec2(3, lookRow), 0).rgb;
  p_ckTow = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_ckMix = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_ckFilaments = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_ckAniso = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_ckRelief = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_ckRough = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_ckCoat = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_ckCoatRough = texelFetch(lookSettings, ivec2(11, lookRow), 0).r;
  p_ckMottle = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 ckQ = uv / p_ckTow;
    vec2 ckCell = floor(ckQ);
    vec2 ckF = fract(ckQ);
    // 2/2 twill: the warp (along v, tow number ckCell.x) floats over the weft for two rows, then under it for two,
    // stepping one each row
    float ckPhase = mod(ckCell.x + ckCell.y, 4.0);
    float ckWarpUp = step(ckPhase, 1.5);
    // across the tow on top (0 to 1) and along its float (0 at one end, 1 at the other)
    float ckAcross = mix(ckF.y, ckF.x, ckWarpUp);
    float ckAlong = mix((ckPhase - 2.0 + ckF.x) * 0.5, (ckPhase + ckF.y) * 0.5, ckWarpUp);
    float ckN = mix(ckCell.y, ckCell.x, ckWarpUp);
    float ckYarnTop = ckYarn(ckN, ckWarpUp, p_ckMix);
    // the tow's crown: flat on top, rolling down at its edges and diving at its float's ends
    float ckEdge = smoothstep(0.0, 0.1, ckAcross) * smoothstep(0.0, 0.1, 1.0 - ckAcross);
    float ckEnds = smoothstep(0.0, 0.07, ckAlong) * smoothstep(0.0, 0.07, 1.0 - ckAlong);
    float ckCrown = ckEdge * ckEnds;
    // the filaments: fine lines along the tow, faded out finer than a pixel
    float ckFilF = kfade(p_ckTow / max(p_ckFilaments, 1.0) * 2.0);
    float ckFil = 0.5 + 0.5 * sin(ckAcross * p_ckFilaments * 6.2831853 + kh(vec2(ckN, seed)) * 6.28);
    ckFil = mix(0.5, ckFil * (0.8 + 0.4 * kn(vec2(ckAlong * 6.0, ckAcross * p_ckFilaments) + ckN)), ckFilF);
    // the tow's way in the view, from the uv's change across the pixel, and how square it lies to the line of sight
    vec3 ckP = -vViewPosition;
    vec3 ckDx = dFdx(ckP), ckDy = dFdy(ckP);
    vec2 ckUx = dFdx(uv), ckUy = dFdy(uv);
    float ckDet = ckUx.x * ckUy.y - ckUx.y * ckUy.x;
    float ckS = abs(ckDet) > 1e-14 ? 1.0 / ckDet : 0.0;
    vec3 ckTu = (ckDx * ckUy.y - ckDy * ckUx.y) * ckS;
    vec3 ckTv = (ckDy * ckUx.x - ckDx * ckUy.x) * ckS;
    vec3 ckWay = normalize(mix(ckTu, ckTv, ckWarpUp) + vec3(1e-9));
    vec3 ckEye = normalize(ckP);
    // square to the eye its filaments light up, along it they go dark: a carbon twill's chequer turning over
    float ckSquare = 1.0 - abs(dot(ckEye, ckWay));
    float ckLit = mix(1.0 - p_ckAniso, 1.0, ckSquare * ckSquare);
    vec3 ckBase = ckYarnTop > 0.5 ? p_ckAramid : p_ckCarbon;
    vec3 ckShine = ckYarnTop > 0.5 ? p_ckAramidShine : p_ckCarbonShine;
    vec3 ckCol = ckBase * (0.85 + 0.3 * ckFil) + ckShine * ckLit * ckCrown * (0.7 + 0.6 * ckFil);
    // where the tow dives under its neighbour, the gap between them in the resin's shadow
    ckCol *= mix(0.55, 1.0, ckCrown);
    // finer than a pixel: the cloth's mean, its share of aramid by the mix
    float ckF2 = kfade(p_ckTow * 1.5);
    float ckShare = p_ckMix < 0.5 ? 0.0 : 0.5;
    vec3 ckMean = mix(p_ckCarbon + p_ckCarbonShine * 0.45, p_ckAramid + p_ckAramidShine * 0.45, ckShare) * 0.8;
    ckCol = mix(ckMean, ckCol, ckF2);
    // the resin: a little uneven over the tub, thicker and glossier in patches, the cloth a shade darker under it
    float ckMot = kfbm4(uv * 3.0 + seed * 7.0);
    ckCol *= 1.0 - p_ckMottle * 0.25 * (ckMot - 0.5);
    k.colour = ckCol;
    k.metal = 0.0;
    k.rough = mix(p_ckRough, p_ckRough + 0.15, ckYarnTop);
    k.height = p_ckRelief * mix(0.5, ckCrown * (0.9 + 0.1 * ckFil), ckF2);
    k.ao = mix(0.6, 1.0, mix(0.7, ckCrown, ckF2));
    k.clearcoat = p_ckCoat;
    k.clearcoatRough = clamp(p_ckCoatRough + p_ckMottle * 0.15 * (ckMot - 0.5), 0.0, 1.0);

}





void look_65(inout Look k, int lookRow) {
  p_omColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_omPitchV = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_omBarV = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_omDeepU = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_omPitchU = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_omBarU = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_omDeepV = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_omRound = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_omTwist = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_omDiagonal = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_omSpangle = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_omRough = texelFetch(lookSettings, ivec2(11, lookRow), 0).r;
  p_omMetal = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  p_omSide = texelFetch(lookSettings, ivec2(13, lookRow), 0).r;
  p_omGrime = texelFetch(lookSettings, ivec2(14, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the panel's ways in the world (u's and v's), from the uv's change across the pixel, so the eye's slant across
    // each set of bars is known
    // a chain-link's diamonds: both sets of wires turned 45 degrees on the uv
    vec2 omUv = p_omDiagonal > 0.5 ? mat2(0.7071, 0.7071, -0.7071, 0.7071) * uv : uv;
    vec3 omDpx = dFdx(wp), omDpy = dFdy(wp);
    vec2 omDux = dFdx(omUv), omDuy = dFdy(omUv);
    float omDet = omDux.x * omDuy.y - omDux.y * omDuy.x;
    vec3 omTu = abs(omDet) > 1e-14 ? (omDpx * omDuy.y - omDpy * omDux.y) / omDet : vec3(1.0, 0.0, 0.0);
    vec3 omTv = abs(omDet) > 1e-14 ? (omDpy * omDux.x - omDpx * omDuy.x) / omDet : vec3(0.0, 0.0, 1.0);
    omTu = dot(omTu, omTu) > 1e-12 ? normalize(omTu) : vec3(1.0, 0.0, 0.0);
    omTv = dot(omTv, omTv) > 1e-12 ? normalize(omTv) : vec3(0.0, 0.0, 1.0);
    vec3 omN = normalize(wn);
    vec3 omV = normalize(cameraPosition - wp);
    float omVn = max(abs(dot(omV, omN)), 0.08);
    // the eye's slant across each set: how far, per metre of a bar's depth, it sees down the bar's side, and to which
    // side of the bar (away from the eye)
    float omVv = dot(omV, omTv), omVu = dot(omV, omTu);
    float omSideLenV = min(p_omDeepU * abs(omVv) / omVn, p_omPitchV - p_omBarV);
    float omSideLenU = min(p_omDeepV * abs(omVu) / omVn, p_omPitchU - p_omBarU);
    float omShiftV = -sign(omVv) * omSideLenV * 0.5;
    float omShiftU = -sign(omVu) * omSideLenU * 0.5;
    vec2 omF = vec2(length(vec2(omDux.x, omDuy.x)), length(vec2(omDux.y, omDuy.y))) * 1.2;
    // each set's cover: its tops and the sides the eye sees, and its tops alone
    float omA = omCover(omUv.y - omShiftV, p_omPitchV, p_omBarV + omSideLenV, omF.y);
    float omB = omCover(omUv.x - omShiftU, p_omPitchU, p_omBarU + omSideLenU, omF.x);
    float omTopA = omCover(omUv.y, p_omPitchV, p_omBarV, omF.y);
    float omTopB = omCover(omUv.x, p_omPitchU, p_omBarU, omF.x);
    float omCov = 1.0 - (1.0 - omA) * (1.0 - omB);
    // the share of what is seen that is a bar's side, not its top (the first set lies over the second where they cross)
    float omSideA = max(omA - omTopA, 0.0);
    float omSideB = max(omB - omTopB, 0.0) * (1.0 - omTopA);
    float omSide = clamp((omSideA + omSideB) / max(omCov, 1e-4), 0.0, 1.0);
    // across a bar, -1 to 1 (for the round wires' shading), and along the cross bars' twist
    float omPv = omUv.y - floor(omUv.y / p_omPitchV + 0.5) * p_omPitchV;
    float omPu = omUv.x - floor(omUv.x / p_omPitchU + 0.5) * p_omPitchU;
    float omXv = clamp(omPv / (p_omBarV * 0.5), -1.0, 1.0);
    float omXu = clamp(omPu / (p_omBarU * 0.5), -1.0, 1.0);
    float omFadeV = kfade(p_omBarV), omFadeU = kfade(p_omBarU);
    float omOnA = omTopA / max(omCov, 1e-4);
    float omOnB = omTopB * (1.0 - omTopA) / max(omCov, 1e-4);
    float omRoundA = 1.0 - p_omRound * 0.5 * omXv * omXv * omFadeV;
    float omRoundB = 1.0 - p_omRound * 0.5 * omXu * omXu * omFadeU;
    float omTw = 1.0;
    if (p_omTwist > 0.0) {
      float omFacet = step(0.5, fract(omUv.y * p_omTwist + omXu * 0.5));
      omTw = mix(0.94, 0.78 + 0.32 * omFacet, kfade(1.0 / p_omTwist));
    }
    float omShade = mix(1.0, omRoundA, omOnA) * mix(1.0, omRoundB * omTw, omOnB) * (1.0 - p_omSide * omSide);
    // the finish: the zinc's spangle or the coat's even colour, grime in a slow cloud
    float omId, omE;
    kvor(uv * 30.0 + seed * 11.0, omId, omE);
    float omSp = 1.0 + p_omSpangle * 0.12 * (omId - 0.5) * 2.0 * kfade(0.03);
    float omG = p_omGrime * smoothstep(0.35, 0.8, kfbm4(uv * 2.5 + seed + 3.0));
    k.colour = p_omColour * omSp * (1.0 - 0.35 * omG) * omShade;
    k.metal = mix(p_omMetal, p_omMetal * 0.5, omG);
    k.rough = clamp(p_omRough + p_omSpangle * 0.1 * (kh1(omId * 17.0) - 0.5) + 0.25 * omG, 0.05, 1.0);
    k.alpha = omCov;
    k.ao = 1.0 - 0.4 * omSide;

}





void look_70(inout Look k, int lookRow) {
  p_vcColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_vcRich = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_vcCloud = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_vcPeel = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_vcRough = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_vcCoatRough = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 vcV = normalize(cameraPosition - wp);
    float vcFace = clamp(abs(dot(vcV, normalize(wn))), 0.0, 1.0);
    float vcCl = kfbm(uv * 6.0 + seed) - 0.5;
    vec3 vcC = p_vcColour * (1.0 + p_vcCloud * vcCl * 2.0);
    // thicker glaze seen square: the colour deeper and more saturated
    vcC = mix(vcC, pow(max(vcC, vec3(0.0)), vec3(1.15)) * 1.1, p_vcRich * vcFace);
    k.colour = vcC;
    k.rough = p_vcRough;
    k.metal = 0.0;
    k.height = p_vcPeel * mix(0.0, kn(uv * 180.0 + seed), kfade(0.004));
    k.clearcoat = 1.0;
    k.clearcoatRough = p_vcCoatRough;

}








void look_78(inout Look k, int lookRow) {
  p_cdDark = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_cdLight = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_cdLay = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_cdRound = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_cdRough = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_cdCoat = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_cdRelief = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // three strands round its girth, each leaning along its lay
    float cdT = fract(uv.x / p_cdLay + uv.y * 3.0 / p_cdRound);
    float cdS = smoothstep(0.0, 0.3, cdT) * smoothstep(1.0, 0.7, cdT);
    float cdF = kn(vec2(uv.x * 900.0 + uv.y * 300.0, uv.y * 120.0) + seed) * kfade(0.0015);
    float cdV = kfade(p_cdLay * 0.5);
    float cdM = mix(0.5, cdS, cdV);
    k.colour = mix(p_cdDark, p_cdLight, cdM) * (0.88 + 0.24 * cdF) * (0.9 + 0.2 * kfbm(uv * 20.0 + seed));
    k.rough = p_cdRough;
    k.clearcoat = p_cdCoat * cdM;
    k.clearcoatRough = 0.35;
    k.height = p_cdRelief * cdM;

}





void look_83(inout Look k, int lookRow) {
  p_erScale = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_erRustColour = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_erRustDark = texelFetch(lookSettings, ivec2(2, lookRow), 0).rgb;
  p_erBakeColour = texelFetch(lookSettings, ivec2(3, lookRow), 0).rgb;
  p_erDustColour = texelFetch(lookSettings, ivec2(4, lookRow), 0).rgb;
  p_erPatches = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_erRust = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_erBake = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_erDust = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_erSoot = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_erGrain = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_erRelief = texelFetch(lookSettings, ivec2(11, lookRow), 0).r;
  p_erRough = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  p_erMetal = texelFetch(lookSettings, ivec2(13, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float erG = mix(0.5, kn(uv * p_erGrain + seed), kfade(2.0 / p_erGrain));
    float erG2 = mix(0.5, kn(uv * p_erGrain * 0.31 + seed + 4.0), kfade(5.0 / p_erGrain));
    float erDown = smoothstep(0.2, -0.8, wn.y);
    float erUp = smoothstep(0.2, 0.9, wn.y);
    // rust: blooms through the scale, more on the undersides, a ragged edge where the scale flakes
    float erF = kfbm4(uv * p_erPatches + seed + 2.0) + 0.25 * erDown + 0.15 * (erG2 - 0.5);
    float erR = p_erRust * smoothstep(0.42, 0.62, erF);
    float erEdge = smoothstep(0.38, 0.45, erF) * (1.0 - smoothstep(0.45, 0.55, erF)) * kfade(3.0 / p_erGrain);
    vec3 erC = p_erScale * (0.85 + 0.3 * erG);
    vec3 erRc = mix(p_erRustDark, p_erRustColour, smoothstep(0.3, 0.8, kfbm(uv * p_erPatches * 5.0 + seed + 8.0)));
    erC = mix(erC, erRc * (0.85 + 0.3 * erG), erR);
    // baked dark where it ran hottest
    float erB = p_erBake * smoothstep(0.45, 0.8, kfbm(uv * p_erPatches * 0.5 + seed + 13.0));
    erC = mix(erC, p_erBakeColour, erB * (1.0 - 0.5 * erR));
    // soot in drifts, road dust on the tops
    float erS = p_erSoot * smoothstep(0.5, 0.85, kfbm(uv * p_erPatches * 1.7 + seed + 21.0));
    erC = mix(erC, vec3(0.012, 0.011, 0.01), erS);
    float erD = p_erDust * erUp * smoothstep(0.35, 0.7, kfbm(uv * p_erPatches * 2.0 + seed + 31.0));
    erC = mix(erC, p_erDustColour, erD);
    k.colour = erC;
    k.metal = p_erMetal * (1.0 - erR) * (1.0 - erD) * (1.0 - erS);
    k.rough = clamp(p_erRough + 0.1 * (erG - 0.5) + 0.08 * erR + 0.1 * erD - 0.1 * erB, 0.2, 1.0);
    k.height = p_erRelief * (0.5 * (erG - 0.5) + 0.4 * erR * (erG2 - 0.5) + 1.2 * erEdge);
    k.ao = 1.0 - 0.25 * erEdge;

}











void look_94(inout Look k, int lookRow) {
  p_bhColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_bhGap = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_bhBands = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_bhWires = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_bhRelief = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_bhRough = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_bhMetal = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_bhGrime = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_bhGrimeColour = texelFetch(lookSettings, ivec2(8, lookRow), 0).rgb;
