    float rep = p_wcRepeat;
    if (p_wcKind < 0.5) {
      // a stripe is drawn while a pixel is no wider than it, its edges softened over the pixel; seen from farther
      // off it is its share of the cloth's colour
      float s = wcBand(wcUv.x, rep, p_wcLine);
      float sMean = p_wcLine / rep;
      s = mix(sMean, s, kfade(p_wcLine * 2.0));
      col = mix(col, p_wcColour2, s);
    } else {
